var errorTitle=window.localization.error;$(document).ready(()=>{$(document).on("click",".delete-post",function(event){event.preventDefault();var $this=$(this),dataurl=$this.data("url"),id=$this.data("id");$Confirm({},function(result){result.value&&$.ajax({url:dataurl,type:"Get",dataType:"json",data:{}}).done(function(data){if(data.success)$notification.success("",window.localization.deleted_successfully,2e3,"fa fa-check"),$this.parents('tr[id="tr-'+id+'"]').remove();else{var errors=data.errors;errors.length>0&&(txt=MakeErrorsMsg(errors),$notification.error("",txt,3500,"fa fa-exclamation-circle"))}}).fail(function(jqXHR,Status){$notification.error(errorTitle,jqXHR.statusText,2e3,"fa fa-exclamation-circle")})})}),$(".toggle_publish").on("change",function(event){let $this=$(this),link=$this.data("url");console.log($this.prop("checked")),fetch(link,{headers:{"Content-Type":"application/json; charset=utf-8"}}).then(res=>res.json()).then(response=>{}).catch(err=>{$notification.error(errorTitle,jqXHR.statusText,2e3,"fa fa-exclamation-circle")})})});